import numpy as np
import pandas as pd

def generate_signals(df: pd.DataFrame) -> pd.Series:
    # Calculate SMA(35) and STD(35)
    df['SMA_35'] = df['close'].rolling(window=35).mean()
    df['STD_35'] = df['close'].rolling(window=35).std()

    # Initialize the position series
    positions = pd.Series(0, index=df.index)

    # Iterate over the DataFrame
    for i in range(len(df)):
        if i < 34:
            # Warm-up period
            positions.iloc[i] = 0
        else:
            # Apply the strategy
            if positions.iloc[i-1] == 0:
                # Flat
                if df['close'].iloc[i] < df['SMA_35'].iloc[i] - 1.25 * df['STD_35'].iloc[i]:
                    positions.iloc[i] = 1
            elif positions.iloc[i-1] == 1:
                # Long
                if df['close'].iloc[i] >= df['SMA_35'].iloc[i] - 1 * df['STD_35'].iloc[i]:
                    positions.iloc[i] = 0

    return positions
