import numpy as np
import pandas as pd

def generate_signals(df: pd.DataFrame) -> pd.Series:
    # Initialize the signals series with zeros
    signals = pd.Series(0, index=df.index)

    # Calculate the 12-bar highest close
    rolling_max_12 = df['close'].rolling(window=12).max()

    # Entry signal: close > prior 12-bar highest close
    for i in range(len(df)):
        if i < 11:
            signals[i] = 0  # Warm-up period
        elif df['close'].iloc[i] > rolling_max_12.iloc[i]:
            signals[i] = -1  # Short position

    # Exit the short position after 3 bars
    for i in range(len(df)):
        if signals[i] == -1:
            if i < 3:
                signals[i] = 0  # Not enough bars to exit
            else:
                signals[i] = 0  # Exit after 3 bars

    return signals
